-- Golden Oremar: ürün sağlık / beslenme bilgileri ve ürün bilgi alanları (v1)
--
-- public.content_entries (content_type='product_health', yayındaki kayıt):
-- * summary: ürünün sağlık / beslenme bilgisi (ürün sayfasında
--   "Ürünün Sağlık Bilgileri" bölümünde gösterilir),
-- * metadata.productInfoV1: içindekiler ve kullanım önerileri,
-- * metadata.safetyV2: saklama, hazırlama, ek uyarılar ve alerjenler
--   (payload'da olmayan alanlar mevcut değeriyle korunur),
-- * metadata.editorialV1: yönetici editörünün okuduğu ayna alanlar.
--
-- Metinler hastalık önleme / tedavi iddiası içermez. Besin değeri sayıları
-- (nutrition), fiyat, stok, ağırlık, raf ömrü ve sertifika alanlarına
-- dokunulmaz. İçerik id'si ile eşleşir ve idempotenttir.

with v(id, summary, payload) as (
values
  ('a56b8615-263a-4d07-9f88-6f9e5de7932b'::uuid, $go$Petek bal, bal ve balmumundan oluşur. Bal ağırlıklı olarak fruktoz ve glikozdan oluşan doğal şekerler içerdiği için enerji veren bir gıdadır; az miktarda mineral, organik asit ve bitkisel bileşikler de barındırır. Balmumu sindirilmeden vücuttan geçer. Dengeli beslenmenin parçası olarak ölçülü tüketilmesi önerilir. Şeker içeriği yüksek olduğundan diyabeti olanların ve kan şekeri takibi yapanların tüketim miktarını hekimi veya diyetisyeniyle belirlemesi önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Petekli karakovan balı (bal ve balmumu)"],"usageNotes":["Peteği temiz ve kuru bir bıçakla, ihtiyacınız kadar dilimleyin.","Mumuyla birlikte yenebilir; dilerseniz mumu çiğneyip ayırabilirsiniz.","Kahvaltıda tereyağı, kaymak veya peynirle birlikte sunulabilir."],"storage":["Kutusu kapalı olarak oda sıcaklığında, kuru ve doğrudan güneş almayan bir yerde saklayın.","Buzdolabında saklamanız gerekmez; soğukta petek sertleşir ve bal daha çabuk kristalleşir.","Kristalleşme balın doğal bir özelliğidir ve tek başına bozulma göstergesi değildir.","Peteğe ıslak bıçak veya kaşık değdirmeyin; nem balın kalitesini bozar."],"preparation":["Dilimlemeden önce ellerinizi ve kullanacağınız aracı yıkayıp kurulayın.","Kestiğiniz parçayı ayrı bir tabağa alın; kalan peteği kutusunda kapalı tutun."]}$go$::jsonb), -- 101 daglica-karakovan-petek-bali-101
  ('50461889-a391-46b8-96ec-adbe41040fde'::uuid, $go$Çiçek balı, ağırlıklı olarak fruktoz ve glikozdan oluşan doğal şekerler içerir; bu nedenle enerji veren bir gıdadır. Az miktarda mineral, organik asit ve çiçek kaynaklı bitkisel bileşikler barındırır. Dengeli beslenmenin parçası olarak ölçülü tüketilmesi önerilir. Şeker içeriği yüksek olduğundan diyabeti olanların ve kan şekeri takibi yapanların tüketim miktarını hekimi veya diyetisyeniyle belirlemesi önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Süzme çiçek balı"],"usageNotes":["Kahvaltıda tereyağı veya kaymakla, yoğurdun ya da yulafın üstünde tüketilebilir.","Sıcak içeceklere eklenecekse içeceği biraz ılıttıktan sonra karıştırın; kaynar sıcaklık balın aromasını zayıflatır.","Şekerlenen balı 40°C'yi geçmeyen ılık su banyosunda bekleterek yeniden akışkan hâle getirebilirsiniz."],"storage":["Kapağı sıkıca kapalı olarak oda sıcaklığında, kuru ve doğrudan güneş almayan bir yerde saklayın.","Buzdolabında saklamanız gerekmez; soğukta bal daha çabuk kristalleşir.","Kristalleşme balın doğal bir özelliğidir ve tek başına bozulma göstergesi değildir.","Bala ıslak kaşık değdirmeyin; nem ve su, balın kalitesini bozar."],"preparation":["Bal almak için her zaman temiz ve kuru bir kaşık kullanın.","Kavanozu mikrodalgada veya doğrudan ateşte ısıtmayın."]}$go$::jsonb), -- 102 bercelan-yaylasi-bahar-cicek-bali-102
  ('bf403287-6c81-4819-b605-7873e7f19f69'::uuid, $go$Meşe balı bir salgı balıdır. Çiçek ballarında olduğu gibi ağırlıklı olarak fruktoz ve glikozdan oluşan doğal şekerler içerir; koyu renkli salgı balları genellikle mineral madde bakımından açık renkli ballardan daha zengindir. Enerji değeri yüksek bir gıda olduğundan dengeli beslenmenin parçası olarak ölçülü tüketilmesi önerilir. Şeker içeriği yüksek olduğundan diyabeti olanların ve kan şekeri takibi yapanların tüketim miktarını hekimi veya diyetisyeniyle belirlemesi önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Süzme meşe (salgı) balı"],"usageNotes":["Kahvaltıda peynir, tereyağı veya tahinle birlikte tüketilebilir.","Güçlü aroması nedeniyle tatlı ve hamur işlerinde şeker yerine az miktarda kullanılabilir.","Sıcak içeceklere eklenecekse içeceği biraz ılıttıktan sonra karıştırın."],"storage":["Kapağı sıkıca kapalı olarak oda sıcaklığında, kuru ve doğrudan güneş almayan bir yerde saklayın.","Buzdolabında saklamanız gerekmez; soğukta bal daha çabuk kristalleşir.","Kristalleşme balın doğal bir özelliğidir ve tek başına bozulma göstergesi değildir.","Bala ıslak kaşık değdirmeyin; nem ve su, balın kalitesini bozar."],"preparation":["Bal almak için her zaman temiz ve kuru bir kaşık kullanın.","Kavanozu mikrodalgada veya doğrudan ateşte ısıtmayın."]}$go$::jsonb), -- 103 avasin-mese-bali-103
  ('9cf67504-4117-48f2-a7d2-b35a642cc292'::uuid, $go$Tulum peyniri protein ve kalsiyum kaynağıdır. Olgunlaştırılmış peynirlerde olduğu gibi yağ ve tuz içeriği de yüksektir; bu nedenle dengeli beslenmenin parçası olarak ölçülü porsiyonlarla tüketilmesi önerilir. Tuz tüketimini sınırlaması gerekenlerin porsiyon miktarına dikkat etmesi önerilir. Süt içerir; süt alerjisi olanlar tüketmemelidir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Süt","Şirden mayası","Tuz"],"usageNotes":["Kahvaltıda domates, salatalık ve sıcak ekmekle sunulabilir.","Ufalanarak börek, pide ve gözleme içlerinde ya da sıcak makarnada kullanılabilir.","Servisten yaklaşık yarım saat önce buzdolabından çıkarırsanız aroması daha iyi açılır."],"storage":["Teslimattan sonra gecikmeden buzdolabına alın.","Soğuk ürünleri 4°C veya altında tutun; ambalaj veya lot etiketi daha sıkı bir koşul belirtiyorsa etiketi izleyin.","Soğuk zincir bozulduysa ürünü tüketmeden önce güvenlik açısından değerlendirin.","Açtıktan sonra peyniri hava almayacak şekilde sarın veya kapaklı bir kapta saklayın."],"preparation":["Peyniri temiz bir bıçak ve kesme tahtasıyla kesin.","Kesilen parçayı oda sıcaklığında uzun süre açıkta bırakmayın."],"addWarnings":["Geleneksel köy peynirleri çiğ sütten yapılabilir; hamileler, küçük çocuklar, yaşlılar ve bağışıklığı zayıf kişilerin tüketmeden önce ambalaj bilgisini kontrol etmesi ve hekimine danışması önerilir."]}$go$::jsonb), -- 201 merez-hatun-un-magara-tulum-peyniri-201
  ('97ae8a8b-6ab8-4665-98ea-3833b9dbf99d'::uuid, $go$Tereyağı yoğun bir enerji ve yağ kaynağıdır; içeriğindeki yağın önemli bölümü doymuş yağdır. Doğal olarak A vitamini içerir. Dengeli beslenmenin parçası olarak ölçülü miktarlarda tüketilmesi önerilir. Süt yağından üretildiği için süt alerjisi olanlar tüketmemelidir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["İnek sütü kaymağı"],"usageNotes":["Sıcak ekmeğe sürülerek, pilav, yumurta ve sebze yemeklerinde kullanılabilir.","Yüksek ısıda yakılmamalıdır; kızdırırken ateşi orta seviyede tutun.","Uzun süre saklamak için küçük parçalara bölüp dondurucuda saklayabilirsiniz."],"storage":["Teslimattan sonra gecikmeden buzdolabına alın.","Soğuk ürünleri 4°C veya altında tutun; ambalaj veya lot etiketi daha sıkı bir koşul belirtiyorsa etiketi izleyin.","Soğuk zincir bozulduysa ürünü tüketmeden önce güvenlik açısından değerlendirin.","Kokusunu çekmemesi için keskin kokulu gıdalardan uzakta, kapalı bir kapta saklayın."],"preparation":["İhtiyacınız kadarını temiz bir bıçakla kesip alın; kalanını hemen buzdolabına geri koyun."]}$go$::jsonb), -- 202 naciye-nin-yayik-tereyagi-202
  ('e9af6250-4547-496b-ba10-f4c66b636c58'::uuid, $go$Otlu peynir protein ve kalsiyum kaynağıdır. Salamurada olgunlaştırıldığı için tuz içeriği yüksektir; yağ oranı da olgun peynirlere benzer düzeydedir. Dengeli beslenmenin parçası olarak ölçülü porsiyonlarla tüketilmesi önerilir; tuz tüketimini sınırlaması gerekenler dilimleri bir süre suda bekleterek tuzunu azaltabilir. Süt içerir; süt alerjisi olanlar tüketmemelidir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Süt","Dağ otları (sirmo, heliz, mendo)","Kaya tuzu","Peynir mayası"],"usageNotes":["Tuzunu azaltmak için dilimleri tüketmeden önce bir süre soğuk suda bekletin.","Kahvaltıda, sıcak lavaş veya köy ekmeğiyle sunulabilir.","Rendelenerek veya ufalanarak börek, pide ve omlet içlerinde kullanılabilir."],"storage":["Teslimattan sonra gecikmeden buzdolabına alın.","Soğuk ürünleri 4°C veya altında tutun; ambalaj veya lot etiketi daha sıkı bir koşul belirtiyorsa etiketi izleyin.","Soğuk zincir bozulduysa ürünü tüketmeden önce güvenlik açısından değerlendirin.","Peyniri salamurasının içinde, kapağı kapalı bir kapta saklayın; salamuradan çıkan peynir kurur."],"preparation":["Peyniri salamuradan temiz bir çatal veya maşayla alın; kaba elle dokunmayın."],"addWarnings":["Geleneksel köy peynirleri çiğ sütten yapılabilir; hamileler, küçük çocuklar, yaşlılar ve bağışıklığı zayıf kişilerin tüketmeden önce ambalaj bilgisini kontrol etmesi ve hekimine danışması önerilir."],"allergenText":"Süt içerir. Kullanılan sütün türü ve olası çapraz bulaşma bilgisi için ambalaj etiketini kontrol edin."}$go$::jsonb), -- 203 havahan-in-otlu-dag-peyniri-203
  ('c5b18b0f-108c-4269-80dc-b390dada20b3'::uuid, $go$Süt; protein, kalsiyum, fosfor ve B2 vitamini kaynağıdır ve dengeli beslenmenin temel gıdalarından biridir. Bu ürün çiğ süttür: pastörize edilmemiş süt zararlı mikroorganizmalar taşıyabileceğinden içmeden ve kullanmadan önce mutlaka kaynatılmalıdır. Süt içerir; süt alerjisi veya laktoz hassasiyeti olanların dikkat etmesi önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Çiğ inek sütü"],"usageNotes":["İçmeden ve yoğurt mayalamadan önce sütü tamamen kaynatın, ardından soğutun.","Kaynatınca yüzeyde oluşan kaymağı ayırıp kahvaltıda tüketebilirsiniz.","Kaynatılmış sütü kapalı bir kapta buzdolabında saklayın."],"storage":["Teslimattan sonra gecikmeden buzdolabına alın.","Soğuk ürünleri 4°C veya altında tutun; ambalaj veya lot etiketi daha sıkı bir koşul belirtiyorsa etiketi izleyin.","Soğuk zincir bozulduysa ürünü tüketmeden önce güvenlik açısından değerlendirin.","Kaynatılmış sütü kapağı kapalı olarak buzdolabında saklayın ve birkaç gün içinde tüketin."]}$go$::jsonb), -- 204 gunluk-taze-civik-sut-sagimdan-kapiya-204
  ('42fe699e-4c6a-4952-89f0-cd07f915542b'::uuid, $go$Yayık ayranı yoğurttan elde edildiği için protein ve kalsiyum içerir; yağının önemli kısmı yayıkta tereyağı olarak ayrıldığından yoğurda göre daha hafiftir. Yoğurt kaynaklı canlı mayalar içerebilir. Dengeli beslenmenin parçası olarak öğünlerin yanında tüketilebilir. Süt içerir; süt alerjisi olanlar tüketmemelidir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Köy yoğurdu","Su"],"usageNotes":["İçmeden önce şişeyi hafifçe çalkalayın.","Soğuk servis edin; dilerseniz bardağa bir tutam tuz ekleyebilirsiniz.","Ayran aşı, yayla çorbası gibi yemeklerde de kullanılabilir."],"storage":["Teslimattan sonra gecikmeden buzdolabına alın.","Soğuk ürünleri 4°C veya altında tutun; ambalaj veya lot etiketi daha sıkı bir koşul belirtiyorsa etiketi izleyin.","Soğuk zincir bozulduysa ürünü tüketmeden önce güvenlik açısından değerlendirin.","Açtıktan sonra şişenin kapağını kapalı tutun ve birkaç gün içinde tüketin; zamanla ekşiliği artar."],"preparation":["Doğrudan şişeden içmek yerine temiz bir bardağa alarak tüketin."]}$go$::jsonb), -- 205 taze-yayik-ayrani-canli-kultur-205
  ('052c94f2-20f5-4d46-b3bf-09559b32db98'::uuid, $go$Alabalık yüksek kaliteli protein kaynağıdır; omega-3 yağ asitleri, B12 vitamini ve D vitamini içerir. Haftalık beslenme planında balığa yer vermek, dengeli beslenme önerilerinin bir parçasıdır. Balık alerjisi olanlar tüketmemelidir. Çiğ veya az pişmiş balık tüketilmemelidir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Taze alabalık"],"usageNotes":["Tereyağında, sacda, fırında veya ızgarada pişirilebilir.","Limon, taze soğan, roka ve mevsim salatasıyla servis edilebilir.","Hemen pişirmeyecekseniz temizleyip porsiyonlara ayırarak dondurucuda saklayabilirsiniz."],"storage":["Teslimattan sonra gecikmeden buzdolabına alın.","Soğuk ürünleri 4°C veya altında tutun; ambalaj veya lot etiketi daha sıkı bir koşul belirtiyorsa etiketi izleyin.","Soğuk zincir bozulduysa ürünü tüketmeden önce güvenlik açısından değerlendirin.","Aynı gün veya en geç ertesi gün pişirin; daha uzun saklamak için dondurun ve çözdürdükten sonra yeniden dondurmayın."]}$go$::jsonb), -- 301 avasin-deresi-canli-alabaligi-ozel-hasat-301
  ('0058a4c8-f28c-4d5b-8e8f-1b7353cffa9f'::uuid, $go$Kuzu eti yüksek kaliteli protein kaynağıdır; demir, çinko ve B12 vitamini içerir. Yağ oranı kesime ve parçaya göre değişir; görünür yağı ayırarak ve ölçülü porsiyonlarla tüketilmesi önerilir. Çiğ et, güvenli iç sıcaklığa ulaşana kadar iyice pişirilmelidir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Kuzu eti"],"usageNotes":["Kol ve but fırında veya tandırda, pirzola ızgarada, kuşbaşı kavurma ve güveçte değerlendirilebilir.","Kışlık kavurma için et kendi yağıyla kavrulup soğuduktan sonra kapalı kaplarda saklanabilir.","Hemen kullanmayacağınız parçaları porsiyonlara ayırıp dondurun."],"storage":["Teslimattan sonra gecikmeden buzdolabına alın.","Soğuk ürünleri 4°C veya altında tutun; ambalaj veya lot etiketi daha sıkı bir koşul belirtiyorsa etiketi izleyin.","Soğuk zincir bozulduysa ürünü tüketmeden önce güvenlik açısından değerlendirin.","Çiğ eti buzdolabının en alt rafında, diğer gıdalara damlamayacak şekilde kapalı kapta saklayın.","Dondurulmuş eti buzdolabında çözdürün; çözdürülen eti yeniden dondurmayın."]}$go$::jsonb), -- 302 abidin-in-yayla-kuzusu-302
  ('adccef89-81f4-4048-8e65-a2fa14231d54'::uuid, $go$Oğlak eti yüksek kaliteli protein kaynağıdır; demir, çinko ve B12 vitamini içerir. Kırmızı etler arasında yağ oranı görece düşük olanlardandır. Dengeli beslenmenin parçası olarak ölçülü porsiyonlarla tüketilmesi önerilir. Çiğ et, güvenli iç sıcaklığa ulaşana kadar iyice pişirilmelidir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Oğlak eti"],"usageNotes":["Tandırda, fırında, güveçte veya kuyu kebabı usulüyle kısık ateşte uzun süre pişirilmesi önerilir.","Kekik, sarımsak ve tereyağı oğlak etine iyi eşlik eder.","Hemen kullanmayacağınız parçaları porsiyonlara ayırıp dondurun."],"storage":["Teslimattan sonra gecikmeden buzdolabına alın.","Soğuk ürünleri 4°C veya altında tutun; ambalaj veya lot etiketi daha sıkı bir koşul belirtiyorsa etiketi izleyin.","Soğuk zincir bozulduysa ürünü tüketmeden önce güvenlik açısından değerlendirin.","Çiğ eti buzdolabının en alt rafında, diğer gıdalara damlamayacak şekilde kapalı kapta saklayın.","Dondurulmuş eti buzdolabında çözdürün; çözdürülen eti yeniden dondurmayın."]}$go$::jsonb), -- 303 fahrettin-in-sutten-kesilmis-oglagi-303
  ('917157e5-298f-4ae4-834e-83f11c2e8551'::uuid, $go$Horoz eti yüksek kaliteli protein kaynağıdır; niasin (B3 vitamini), B6 vitamini ve fosfor içerir. Derisi ayrıldığında yağ oranı belirgin şekilde azalır. Kümes hayvanı etleri, en kalın yerinde 74°C iç sıcaklığa ulaşana kadar iyice pişirilmelidir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Horoz eti"],"usageNotes":["Suyuna çorba, haşlama ve bulgur pilavı için idealdir; normal tencerede uzun süre kısık ateşte pişirin.","Düdüklü tencere pişirme süresini kısaltır.","Haşlanan et didiklenip pilavın üstüne konabilir veya fırında kızartılabilir."],"storage":["Teslimattan sonra gecikmeden buzdolabına alın.","Soğuk ürünleri 4°C veya altında tutun; ambalaj veya lot etiketi daha sıkı bir koşul belirtiyorsa etiketi izleyin.","Soğuk zincir bozulduysa ürünü tüketmeden önce güvenlik açısından değerlendirin.","Çiğ eti buzdolabının en alt rafında, diğer gıdalara damlamayacak şekilde kapalı kapta saklayın.","Dondurulmuş eti buzdolabında çözdürün; çözdürülen eti yeniden dondurmayın."]}$go$::jsonb), -- 304 salih-in-meralik-ozgur-horozu-304
  ('1becc2f4-727b-492c-beeb-5d0b38ff4ad5'::uuid, $go$Yumurta yüksek kaliteli protein kaynağıdır; B12 vitamini, B2 vitamini, D vitamini ve kolin içerir. Dengeli beslenmenin parçası olarak tüketilebilir. Yumurta alerjisi olanlar tüketmemelidir. Çiğ veya az pişmiş yumurta tüketilmemeli; sarısı ve beyazı katılaşana kadar pişirilmelidir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Köy tavuğu yumurtası"],"usageNotes":["Sahanda, menemende, haşlama olarak veya hamur işlerinde kullanılabilir.","Tariflerde çifte sarılı bir yumurtanın normal boy bir yumurtadan daha büyük olduğunu hesaba katın.","Kırmadan önce kabuğu kontrol edin; çatlak yumurtayı kullanmayın."],"storage":["Teslimattan sonra gecikmeden buzdolabına alın.","Soğuk ürünleri 4°C veya altında tutun; ambalaj veya lot etiketi daha sıkı bir koşul belirtiyorsa etiketi izleyin.","Soğuk zincir bozulduysa ürünü tüketmeden önce güvenlik açısından değerlendirin.","Yumurtaları viyolünde, sivri ucu aşağı bakacak şekilde buzdolabının kapağında değil iç raflarında saklayın.","Saklamadan önce yıkamayın; kirli görünen yumurtayı yalnızca kullanmadan hemen önce silin."]}$go$::jsonb), -- 305 amine-nin-cifte-sari-koy-yumurtasi-305
  ('3c9d4897-b6a4-4e11-bac1-01fe5f373249'::uuid, $go$Su, vücudun sıvı dengesinin sürdürülmesi için günlük beslenmenin vazgeçilmez bir parçasıdır. Bu kaynak suyunun mineral içeriği ve pH değeri yalnızca doğrulanmış bir analiz raporuna dayanarak paylaşılır; rapor bulunmadan mineral veya sağlık beyanı yapılmaz. Açılan damacananın birkaç gün içinde tüketilmesi ve ağız kısmının temiz tutulması önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Kaynak suyu"],"usageNotes":["Damacanayı temiz bir pompa veya sebil ile kullanın; pompanın ağız kısmını düzenli olarak temizleyin.","Çay, kahve ve yemek yapımında kullanılabilir.","Cam damacana ağırdır; taşırken iki elinizle tutun ve sert zemine çarptırmayın."],"storage":["Serin, kuru ve doğrudan güneş almayan bir yerde, dik olarak saklayın.","Kimyasal ürünlerden, deterjan ve yakıt gibi kokulu maddelerden uzak tutun.","Kapak veya mühür hasarlıysa suyu tüketmeyin."],"preparation":["Damacanayı takmadan önce ellerinizi yıkayın ve ağız kısmını temiz bir bezle silin.","Açtıktan sonra birkaç gün içinde tüketin."]}$go$::jsonb), -- 401 avasin-cam-damacana-suyu-401
  ('3916bb27-7115-442b-853a-3dec259c89de'::uuid, $go$Bu ürün gıda değildir; geleneksel ısı tutma ve pres taşı olarak sunulur. Tıbbi cihaz veya tedavi ürünü değildir ve herhangi bir sağlık amacıyla kullanılması önerilmez. Isıtılmış taş cilde doğrudan temas ettiğinde yanığa yol açabilir; daima bir beze sararak kullanın ve çocukların erişemeyeceği bir yerde soğumaya bırakın. Peynir veya hamur bastırmak için kullanılacaksa önce iyice yıkanmalı ve gıdaya temas eden yüzeyi temiz tutulmalıdır.$go$, $go${"ingredients":[],"usageNotes":["Isı tutma amacıyla kullanırken taşı kalın bir beze veya kılıfa sararak kullanın.","Pres taşı olarak kullanmadan önce yıkayıp kurulayın; gıdayla arasına temiz bir bez veya tabak koyabilirsiniz."],"storage":["Kuru ve serin bir yerde, düşme riski olmayan sağlam bir zeminde saklayın.","Yıkadıktan sonra tamamen kurumasını bekleyin; nemli bırakmayın."],"preparation":["Taşı sobanın üstünde veya fırında kademeli olarak ısıtın; doğrudan aleve koymayın ve suya batırarak ani soğutmayın.","Isıtılmış taşı çıplak elle tutmayın, kalın bir beze sararak kullanın.","Uyurken ciltle doğrudan temas edecek şekilde bırakmayın; küçük çocukların yatağında kullanmayın.","Çatlak veya parça kopması fark ederseniz taşı ısıtmayın."]}$go$::jsonb), -- 402 koyun-efsanevi-beyaz-isitma-pres-tasi-402
  ('5e9eb26b-45a5-4f00-821a-c9be6454b522'::uuid, $go$Bu ürün gıda değildir; soba, şömine ve kuzine için yakacak odundur. Yalnızca bu amaçla yapılmış, bacası düzenli temizlenen soba ve şöminelerde yakılmalıdır. Kapalı ortamda yanma sırasında karbonmonoksit oluşabileceğinden odanın düzenli havalandırılması ve karbonmonoksit dedektörü kullanılması önerilir. Odunu çocukların ve evcil hayvanların oyun alanından uzakta, kuru bir yerde istifleyin.$go$, $go${"ingredients":[],"usageNotes":["Kuzine soba, soba ve şöminede kullanılabilir; tutuşturmak için çıra veya ince çubuk kullanın.","Közü uzun süre dayandığı için kuzinede yemek pişirmeye ve ekmek kızartmaya uygundur."],"storage":["Evin dışında, üstü kapalı, hava alan ve yerden yüksek bir yerde istifleyin.","Soba ve şömine çevresinde yalnızca kısa sürede kullanacağınız miktarı tutun; yanıcı malzemelerden uzak bulundurun."],"preparation":["Benzin, tiner gibi yanıcı sıvılarla tutuşturmayın.","Soba kapağını yanma sırasında kapalı tutun; külü tamamen soğuduktan sonra metal bir kapta boşaltın.","Tel kafesi açarken eldiven kullanın; kıymık ve tel uçlarına dikkat edin.","Bacayı ve soba borularını her kış öncesinde temizletin."]}$go$::jsonb), -- 403 sobalik-mese-yarigi-403
  ('cfaf250a-c2a8-4b42-90c8-4fc2669c9731'::uuid, $go$Tarhana; un, yoğurt ve sebzeden yapılan, fermente edilip kurutulmuş geleneksel bir gıdadır. Karbonhidrat ve protein içerir; yoğurt sayesinde kalsiyum da barındırır. Çorba olarak tüketildiğinde doyurucu bir öğün seçeneğidir. Buğday unu (gluten) ve süt içerir; çölyak, gluten hassasiyeti veya süt alerjisi olanlar tüketmemelidir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Buğday unu","Köy yoğurdu","Mevsim sebzeleri","Ekşi maya"],"usageNotes":["Çorba için 4-5 yemek kaşığı tarhanayı bir bardak soğuk suda 15-20 dakika bekletin, ardından kaynar suya veya et suyuna ekleyip karıştırarak pişirin.","Servis ederken üzerine tereyağında kızdırılmış nane ve pul biber gezdirebilirsiniz.","Pişirirken topaklanmaması için sık sık karıştırın."],"storage":["Keten torbasında veya hava alan bir kapta serin, kuru ve güneş almayan bir yerde saklayın.","Nemli ortamdan ve keskin kokulu ürünlerden uzak tutun.","Nem, küf veya böcek fark ederseniz ürünü kullanmayın."],"preparation":["Tarhanayı önce soğuk suyla ezerek çözdürün; doğrudan kaynar suya atmayın."],"allergensKnown":["Gluten (buğday)","Süt"],"allergenText":"Buğday unu (gluten) ve süt içerir. Çapraz bulaşma bilgisi için ambalaj etiketini kontrol edin."}$go$::jsonb), -- 501 hatun-ana-nin-eksi-maya-gunesi-tarhana-501
  ('6c2d31ab-e65a-47d4-8946-a923d4dd7d6b'::uuid, $go$Kuru dut, kurutma sırasında suyunu kaybettiği için doğal şekerler bakımından yoğun bir meyvedir; lif içerir ve demir, potasyum gibi mineraller barındırır. Enerji değeri taze meyveye göre yüksektir; dengeli beslenmenin parçası olarak ölçülü porsiyonlarla tüketilmesi önerilir. Doğal şeker içeriği yüksek olduğundan diyabeti olanların ve kan şekeri takibi yapanların tüketim miktarını hekimi veya diyetisyeniyle belirlemesi önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Kurutulmuş beyaz dut"],"usageNotes":["Çerez olarak tek başına veya cevizle birlikte tüketilebilir.","Yoğurt, yulaf ve müslinin üstüne serpilebilir.","Kek, kurabiye ve ev yapımı granolada kuru üzüm yerine kullanılabilir."],"storage":["Ambalajı kapalı olarak serin, kuru ve doğrudan güneş almayan bir yerde saklayın.","Açtıktan sonra ağzı sıkıca kapanan bir kaba aktarın; nem ve böceklenmeye karşı koruyun.","Nem, küf veya ambalaj hasarı fark ederseniz ürünü kullanmayın."],"preparation":["Kuru meyve doğal yollarla kurutulduğu için tüketmeden önce ayıklayın; dilerseniz kısa süre yıkayıp kurulayabilirsiniz."]}$go$::jsonb), -- 502 sami-usta-nin-kurutulmus-dag-dutlari-502
  ('4dcf893a-54e0-4cdd-b51d-865132ddc356'::uuid, $go$Üzüm pekmezi, üzüm şırasının koyulaştırılmasıyla elde edilen ve ağırlıklı olarak doğal şekerlerden (fruktoz ve glikoz) oluşan, enerji veren bir gıdadır; az miktarda demir, kalsiyum ve potasyum içerir. Şeker eklenmemiş olsa da şeker içeriği yüksektir; dengeli beslenmenin parçası olarak ölçülü tüketilmesi önerilir. Diyabeti olanların ve kan şekeri takibi yapanların tüketim miktarını hekimi veya diyetisyeniyle belirlemesi önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Üzüm şırası"],"usageNotes":["Kahvaltıda tahinle karıştırılarak ekmekle tüketilebilir.","Helva, irmik tatlısı ve hoşaflarda şeker yerine kullanılabilir.","Yoğurdun veya sütlü tatlıların üstüne gezdirilebilir."],"storage":["Kapağı sıkıca kapalı olarak serin ve güneş almayan bir yerde saklayın.","Pekmeze ıslak veya kirli kaşık değdirmeyin.","Zamanla dipte şeker kristalleri oluşabilir; bu doğaldır, karıştırarak kullanabilirsiniz."],"preparation":["Kullanmadan önce kavanozu karıştırın; kıvamı soğukta koyulaşır, oda sıcaklığında yeniden akışkanlaşır."]}$go$::jsonb), -- 503 kadin-imecesi-odun-atesi-pekmezi-503
  ('50fddbc7-9e32-4867-8112-dc0854a27daf'::uuid, $go$Ceviz bitkisel protein, lif ve ağırlıklı olarak doymamış yağ asitleri içeren besleyici bir kuruyemiştir; bitkisel bir omega-3 yağ asidi olan alfa-linolenik asit (ALA) bakımından kuruyemişler arasında öne çıkar. Ayrıca magnezyum ve fosfor içerir. Enerji değeri yüksek olduğundan günde bir avuç gibi ölçülü porsiyonlarla tüketilmesi önerilir. Ceviz bir sert kabuklu yemiş alerjenidir; alerjisi olanlar tüketmemelidir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Kabuklu ceviz"],"usageNotes":["Kahvaltıda peynir ve balla, çerez olarak kuru dut veya üzümle tüketilebilir.","Baklava, kek, kurabiye, muhammara ve salatalarda kullanılabilir.","Hafifçe kavrulduğunda aroması belirginleşir."],"storage":["Kabuklu cevizi filesinde, serin, kuru ve hava alan bir yerde saklayın.","Kırılmış ceviz içini hava almayan bir kapta buzdolabında veya dondurucuda saklayın; sıcakta yağı acılaşabilir.","Küflü, buruşmuş veya acı kokulu içleri kullanmayın."],"preparation":["Cevizleri kırarken kabuk parçalarının içe karışmamasına dikkat edin.","Küçük çocuklara bütün ceviz vermeyin; boğulma riskine karşı ezerek verin."]}$go$::jsonb), -- 504 husnu-dayi-nin-kagit-kabuklu-cevizi-504
  ('13d6a4df-4843-4459-a3a4-0894ca35c6e7'::uuid, $go$Meşe palamudu unuyla yapılan bu ekmek karbonhidrat ve lif içerir; palamut doğal olarak bitkisel yağ ve bazı mineraller de barındırır. Doyurucu bir ekmektir ve dengeli beslenmenin parçası olarak tüketilebilir. Hamurda palamut ununa ek olarak buğday unu veya buğday bazlı ekşi maya kullanılabileceğinden gluten içerebilir; çölyak veya gluten hassasiyeti olanların içerik bilgisini teyit etmeden tüketmemesi önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":[],"usageNotes":["Dilimleyip kızartarak veya fırında hafifçe ısıtarak tüketebilirsiniz.","Peynir, tereyağı, bal ve çorbalarla iyi gider.","Uzun süre saklamak için dilimleyip porsiyonlar hâlinde dondurun; ihtiyacınız kadarını çıkarıp ısıtın."],"storage":["Bez torbada veya kâğıda sarılı olarak serin ve kuru bir yerde saklayın; birkaç gün içinde tüketin.","Daha uzun saklamak için dilimleyip hava almayan poşetlerde dondurun.","Küf görülen ekmeği tamamen atın; küflü kısmı kesip kalanını tüketmeyin."],"preparation":["Dondurulmuş dilimleri oda sıcaklığında çözdürüp fırında veya tost makinesinde ısıtabilirsiniz."],"allergenText":"Hamurda buğday unu veya buğday bazlı ekşi maya kullanılabilir; gluten içerebilir. Kesin içerik ve alerjen bilgisi için ambalaj etiketini kontrol edin."}$go$::jsonb), -- 505 el-isciligi-mese-palamudu-ekmegi-505
  ('c46b84f8-a3e7-4e8c-879c-dd33f6f32a57'::uuid, $go$Kuru üzüm, suyunu kaybettiği için doğal şekerler bakımından yoğun bir meyvedir; lif, potasyum ve az miktarda demir içerir. Enerji değeri yüksek olduğundan dengeli beslenmenin parçası olarak ölçülü porsiyonlarla tüketilmesi önerilir. Doğal şeker içeriği yüksek olduğundan diyabeti olanların ve kan şekeri takibi yapanların tüketim miktarını hekimi veya diyetisyeniyle belirlemesi önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Kuru üzüm"],"usageNotes":["Çerez olarak cevizle birlikte tüketilebilir.","Pilav, hoşaf, komposto, kek ve kurabiyelerde kullanılabilir.","Hamur işlerinde kullanmadan önce birkaç dakika ılık suda bekletirseniz yumuşar."],"storage":["Bez kesesinde serin, kuru ve kokusuz bir yerde saklayın.","Uzun süre saklayacaksanız ağzı kapalı bir cam kavanoza aktarın.","Nem, küf veya böcek fark ederseniz ürünü kullanmayın."],"preparation":["Kullanmadan önce sap ve yabancı madde kalıntılarını ayıklayın; dilerseniz kısa süre yıkayıp kurulayın."]}$go$::jsonb), -- 506 isli-kaya-uzumleri-tane-kuru-506
  ('5893052a-150a-44aa-ad38-07fb8b5a76ac'::uuid, $go$Kurutulmuş kekik, yemeklerde küçük miktarlarda kullanılan aromatik bir baharattır; bu kullanım miktarlarında besin değerine katkısı sınırlıdır, ancak yemeklerde tuzu azaltırken lezzet katmanın pratik bir yoludur. Bitki çayı olarak demlendiğinde ölçülü tüketilmesi önerilir. Hamileler, emziren anneler, küçük çocuklar ve düzenli ilaç kullananların kekik çayını düzenli tüketmeden önce hekimine danışması önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Kurutulmuş dağ kekiği"],"usageNotes":["Et, köfte, ızgara sebze, çorba, peynir ve salatalara serpilebilir.","Zeytinyağıyla karıştırılarak ekmek banmalık veya marinasyon olarak kullanılabilir.","Bitki çayı için bir tatlı kaşığı kekiği bir bardak sıcak suda 5 dakika demleyip süzün.","Aroması güçlü olduğundan tariflerde az miktarla başlayın."],"storage":["Kapağı kapalı kutusunda serin, kuru ve ışık almayan bir yerde saklayın.","Ocak ve fırın gibi ısı kaynaklarının yanında tutmayın; ısı ve nem aromasını azaltır."],"preparation":["Kekiği pişirmenin sonuna doğru ekleyin; uzun süre kaynarsa aroması azalır.","Kullanmadan önce avucunuzda hafifçe ovarak aromasını açabilirsiniz."]}$go$::jsonb), -- 507 zahter-harmani-dag-kekigi-507
  ('20beca4f-5433-4be3-bbfd-e996e971cc20'::uuid, $go$Kuzu göbeği mantarı düşük kalorili bir gıdadır; protein, lif ve demir başta olmak üzere bazı mineraller içerir. Bu mantar çiğ veya az pişmiş hâlde tüketilmemelidir; çiğken sindirim rahatsızlığına yol açabilen maddeler içerir, bu nedenle iyice pişirilmesi gerekir. Yabani mantarlarda tür doğrulaması hayati önem taşır. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Kuzu göbeği mantarı (Morchella)"],"usageNotes":["Kumunu gidermek için mantarları ikiye kesip soğuk suda kısa süre çalkalayın ve hemen kurulayın.","Tereyağında en az 10-15 dakika iyice soteleyin; çiğ veya az pişmiş tüketmeyin.","Kremalı soslar, pilav, risotto ve et yemeklerinde kullanılabilir."]}$go$::jsonb), -- 601 sessiz-orman-kuzu-gobegi-mantari-601
  ('cf972f0a-d72a-482b-b875-27dc7c50e4f6'::uuid, $go$Kızılcık şurubu, kızılcık meyvesinden hazırlanan konsantre bir içecektir; meyveden gelen organik asitleri ve koyu kırmızı rengini veren antosiyaninleri içerir. Şurup formunda olduğu için şeker içeriği yüksek olabilir; ilave şeker bilgisi ambalaj etiketinden kontrol edilmelidir. Suyla seyreltilerek ve ölçülü tüketilmesi önerilir. Diyabeti olanların ve kan şekeri takibi yapanların tüketim miktarını hekimi veya diyetisyeniyle belirlemesi önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":[],"usageNotes":["Bir ölçü şurubu üç-dört ölçü soğuk suyla seyrelterek hazırlayın.","Yazın buzla, kışın ılık suyla servis edilebilir.","Dondurma, sütlaç ve yoğurdun üstüne birkaç damla gezdirilebilir."],"storage":["Açılmamış şişeyi serin ve güneş almayan bir yerde saklayın.","Açtıktan sonra kapağını sıkıca kapatıp buzdolabında saklayın.","Kapak veya mühür hasarlıysa, köpürme ya da ekşi koku fark ederseniz tüketmeyin."],"preparation":["Kullanmadan önce şişeyi çalkalayın; dipte doğal tortu oluşabilir."]}$go$::jsonb), -- 602 kan-kirmizi-yabani-kizilcik-surubu-seti-602
  ('31dc6593-249b-4d29-b722-a88fa936f543'::uuid, $go$Kaya tuzu ağırlıklı olarak sodyum klorürden oluşur. Tuz, yemeklerde lezzet vermek ve turşu, salamura gibi geleneksel yöntemlerle gıdaları saklamak için kullanılır; ancak fazla tuz tüketimi önerilmez. Dünya Sağlık Örgütü yetişkinler için günlük tuz tüketiminin 5 gramın altında tutulmasını önerir. Bu tuz rafine edilmediği ve iyot eklenmediği için iyot ihtiyacınızı iyotlu sofra tuzu ve diğer besinlerle karşılamanız önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Kaya tuzu"],"usageNotes":["İri parçaları turşu, salamura, peynir tuzlama ve et kurutmada doğrudan kullanabilirsiniz.","Sofra tuzu olarak kullanmak için havanda dövün veya tuz değirmeninde çekin.","Kullanmadan önce parçaları gözden geçirip yabancı madde varsa ayırın."],"storage":["Ağzı kapalı çuvalında veya kapaklı bir kapta, kuru bir yerde saklayın; tuz nem çeker.","Metal kaplarda uzun süre bekletmeyin."],"preparation":["İri parçaları kırarken göz koruması kullanmanız ve küçük parçaların sıçramasına dikkat etmeniz önerilir."]}$go$::jsonb), -- 603 kirik-tas-kaya-tuzu-blogu-kristal-603
  ('a1452817-0279-42c3-bbbc-b1b6f9881d3a'::uuid, $go$İç yağ yoğun bir enerji ve hayvansal yağ kaynağıdır; yağının önemli bir bölümü doymuş yağdır. Lezzet için az miktarda kullanılması ve dengeli beslenmenin parçası olarak ölçülü tüketilmesi önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Eritilmiş kuzu iç yağı"],"usageNotes":["Kavurma, pilav, keşkek ve hamur işlerinde az miktarda kullanılabilir.","Yüksek ısıya dayanıklı olduğu için kızartmalarda kullanılabilir.","Kışlık kavurmanın üstünü kapatmak için eritilerek dökülebilir."],"storage":["Teslimattan sonra gecikmeden buzdolabına alın.","Soğuk ürünleri 4°C veya altında tutun; ambalaj veya lot etiketi daha sıkı bir koşul belirtiyorsa etiketi izleyin.","Soğuk zincir bozulduysa ürünü tüketmeden önce güvenlik açısından değerlendirin.","Kullandıktan sonra kapağını kapatın; yağa su veya yemek artığı karıştırmayın."],"preparation":["Yağı temiz ve kuru bir kaşıkla alın.","Kızgın yağa su değdirmeyin; sıçrayarak yanığa yol açabilir."]}$go$::jsonb), -- 701 gunes-sirri-guzu-yagi-ic-yag-701
  ('a07c0886-330a-4614-844a-14436376cb7c'::uuid, $go$Bamya düşük kalorili bir sebzedir; lif, C vitamini, K vitamini, folat ve magnezyum içerir. Kurutma sırasında suyunu kaybettiği için besin öğeleri ağırlığına göre daha yoğundur; C vitamini ise kurutma ve pişirme sırasında kısmen azalır. Bamyanın kendine özgü kıvamını, içindeki doğal ve suda çözünen lif (müsilaj) verir. Dengeli beslenmenin parçası olarak tüketilebilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Kurutulmuş çiçek bamyası"],"usageNotes":["Pişirmeden önce ipinden ayırıp sıcak suda 15-20 dakika bekleterek yumuşatın.","Sünmesini azaltmak için limonlu veya sirkeli suda kısa süre haşlayıp süzün.","Etli bamya, zeytinyağlı bamya ve ekşili çorbalarda kullanılabilir."],"storage":["Dizi hâlinde, kuru ve hava alan bir yerde asılı olarak veya bez torbada saklayın.","Nemli ortamdan uzak tutun; nem küflenmeye yol açabilir.","Küf veya böcek fark ederseniz ürünü kullanmayın."],"preparation":["Kullanmadan önce sapları ve ip kalıntılarını temizleyin, bamyaları yıkayın."]}$go$::jsonb), -- 702 sabir-kurutmasi-cicek-bamyasi-702
  ('cd34e36c-8122-4912-937a-41f47a1cc308'::uuid, $go$Kurut, süzülüp kurutulmuş yoğurttan yapıldığı için protein ve kalsiyum bakımından yoğundur. Kurutma ve saklama için tuz eklendiğinden tuz içeriği yüksektir; sulandırılarak ve ölçülü kullanılması önerilir. Süt içerir; süt alerjisi olanlar tüketmemelidir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Süzme yoğurt","Tuz","Dağ kekiği"],"usageNotes":["Kullanmadan önce parçaları kırıp birkaç saat ılık suda bekletin, ardından ezerek veya blenderdan geçirerek sulandırın.","Elde edilen sos mantı, erişte, hamur yemekleri ve haşlanmış sebzelerin üzerine dökülebilir.","Çorbalara ekşilik vermek için az miktarda eklenebilir."],"storage":["Bez çuvalında serin, kuru ve hava alan bir yerde saklayın.","Nemli ortamdan uzak tutun; nem çeken kurut yumuşar ve küflenebilir.","Sulandırılmış kurutu buzdolabında saklayın ve birkaç gün içinde tüketin."],"preparation":["Kurut çok sert olduğundan havanda veya temiz bir bez içinde kırarak kullanın."]}$go$::jsonb), -- 703 kekik-aromali-kesik-yogurt-kurud-703
  ('ded0cf3e-8d48-48e2-99a7-8c9bd180dab2'::uuid, $go$Bu ürün gıda değildir; gıdayla temas eden el yapımı ahşap mutfak eşyasıdır. Vernik veya boya kullanılmadığı üretici beyanına dayanır. Ahşap gözenekli bir malzeme olduğundan her kullanımdan sonra sıcak su ve az deterjanla elde yıkanmalı, iyice kurutulmalı ve nemli bırakılmamalıdır. Derin çatlak veya çizik oluşursa bu bölgelerde kir birikebileceğinden ürünün yenilenmesi önerilir.$go$, $go${"ingredients":[],"usageNotes":["Kaşığı yemek karıştırmak ve servis için, tokmağı yayıkta ayran ve tereyağı yapımında kullanabilirsiniz.","Ara sıra gıdaya uygun bir yağla ince bir kat yağlamak ağacın kurumasını ve çatlamasını geciktirir."],"storage":["Kuru ve hava alan bir yerde saklayın; kapalı ve nemli dolaplarda uzun süre bekletmeyin.","Doğrudan ısı kaynaklarının yakınında veya güneş altında bırakmayın; ağaç çatlayabilir."],"preparation":["İlk kullanımdan önce ılık suyla yıkayıp kurutun.","Bulaşık makinesine koymayın ve suda uzun süre bekletmeyin.","Ateşin üstünde veya sıcak tencerenin içinde unutmayın; ahşap ısınıp yanabilir."]}$go$::jsonb), -- 704 el-islemesi-tahta-kasik-ve-yayik-tokmagi-704
  ('bd9cd5be-63f8-4f75-bd70-52b1cd04ea8f'::uuid, $go$Çörek otu tohumu bitkisel yağ, protein ve lif içerir; yemeklerde küçük miktarlarda baharat olarak kullanıldığı için günlük beslenmeye katkısı sınırlıdır. Ürün baharat olarak sunulur; herhangi bir sağlık amacıyla doz önerisi yapılmaz. Hamileler, emziren anneler ve düzenli ilaç kullananların yüksek miktarlarda veya takviye amacıyla tüketmeden önce hekimine danışması önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Çörek otu tohumu"],"usageNotes":["Pide, poğaça, simit ve ekmek hamurlarının üstüne serpilebilir.","Beyaz peynir, salata ve turşulara katılabilir.","Kuru tavada 1-2 dakika hafifçe kavurup ezerek aromasını belirginleştirebilirsiniz."],"storage":["Ağzı kapalı bir kapta serin, kuru ve ışık almayan bir yerde saklayın.","Nemli ortamdan uzak tutun; nem çeken tohum küflenebilir."],"preparation":["Kullanmadan önce gözden geçirip kalmış olabilecek yabancı maddeleri ayıklayın."]}$go$::jsonb), -- 705 buyuk-iskender-corek-otu-tohumu-705
  ('34105eef-30c7-4cb2-a379-5cbab5146e19'::uuid, $go$Kırmızı pul biber, yemeklerde küçük miktarlarda kullanılan bir baharattır; acılığını veren kapsaisin ile doğal renk maddeleri olan karotenoidleri içerir. Kullanım miktarları düşük olduğundan besin değerine katkısı sınırlıdır. Acı baharatlara karşı hassasiyeti olanların, sindirim rahatsızlığı yaşayanların ve küçük çocukların az miktarla başlaması önerilir. Gözle ve yüzle temasından kaçının; kullandıktan sonra ellerinizi yıkayın. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Acı kırmızı biber"],"usageNotes":["Tereyağında kızdırılıp çorba, mantı ve yumurtanın üstüne gezdirilebilir.","Kebap, köfte, salata ve mezelere serpilebilir.","Acıdır; ilk kullanımda az miktarla başlayın."],"storage":["Cam şişesinin kapağı kapalı olarak serin, kuru ve ışık almayan bir yerde saklayın.","Şişeye ıslak kaşık değdirmeyin; nem küflenmeye yol açabilir."],"preparation":["Kullandıktan sonra ellerinizi yıkayın; göze ve yüze temas ettirmeyin."]}$go$::jsonb), -- 706 koylu-isi-aci-kirmizi-biber-706
  ('3b9f3350-b9d6-4bf5-8478-0ae526e2987d'::uuid, $go$Kuşburnu, C vitamini bakımından zengin bir yabani meyvedir; marmelat yapımında pişirme sırasında C vitamininin bir kısmı azalır. Marmelat ayrıca meyveden gelen lif ve doğal renk maddeleri içerir. Şeker ilavesi bilgisi ambalaj etiketinden kontrol edilmelidir; şeker içeriği yüksek olabileceğinden ölçülü tüketilmesi önerilir. Diyabeti olanların ve kan şekeri takibi yapanların tüketim miktarını hekimi veya diyetisyeniyle belirlemesi önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":[],"usageNotes":["Kahvaltıda tereyağıyla ekmeğe sürülebilir.","Krep, pankek, yoğurt ve peynirle birlikte tüketilebilir.","Kurabiye ve tart içlerinde kullanılabilir."],"storage":["Açılmamış kavanozu serin ve güneş almayan bir yerde saklayın.","Açtıktan sonra kapağını sıkıca kapatıp buzdolabında saklayın.","Kavanoza her zaman temiz ve kuru bir kaşıkla dokunun; yüzeyde küf görülürse tüketmeyin."],"preparation":["Kapak şişkinse, köpürme veya ekşi ya da alkol kokusu fark ederseniz ürünü tüketmeyin."]}$go$::jsonb), -- 707 kusburnu-marmelati-707
  ('303fc491-b100-4c60-92c9-751f947bbd08'::uuid, $go$Elma su oranı yüksek, kalorisi düşük bir meyvedir; lif (özellikle pektin) ve C vitamini içerir. Kabuğu da lif ve bitkisel bileşikler barındırdığından iyice yıkanarak kabuğuyla tüketilebilir. Taze meyve ve sebzeler dengeli beslenmenin önemli bir parçasıdır. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Taze elma"],"usageNotes":["Kabuğuyla birlikte taze tüketilebilir.","Elmalı kek, turta, komposto ve fırında elma tatlısı için uygundur.","Kesilen elmanın kararmaması için üzerine birkaç damla limon suyu sıkabilirsiniz."],"storage":["Serin ve karanlık bir yerde veya buzdolabının sebzeliğinde saklayın.","Elmayı diğer meyve ve sebzelerden ayrı tutun; elmanın yaydığı etilen gazı diğer ürünlerin daha çabuk olgunlaşmasına yol açar.","Çürük veya ezik elmaları diğerlerinden ayırın."]}$go$::jsonb), -- 801 hakkari-dag-elmasi-801
  ('e94b75ce-336b-4212-89a9-74227afd4569'::uuid, $go$Domates su oranı yüksek, kalorisi düşük bir sebzedir; C vitamini, potasyum ve folat içerir. Kırmızı rengini veren likopen adlı karotenoidi barındırır; likopen, domates zeytinyağı gibi bir yağla birlikte pişirildiğinde vücut tarafından daha kolay kullanılabilir. Taze meyve ve sebzeler dengeli beslenmenin önemli bir parçasıdır. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Taze domates"],"usageNotes":["Kahvaltıda zeytinyağı ve tuzla, salatalarda ve menemende kullanılabilir.","Salça, sos ve kışlık konserve yapımına uygundur.","Tam kıvamına gelmesi için oda sıcaklığında bir iki gün bekletebilirsiniz."],"storage":["Olgunlaşana kadar oda sıcaklığında, doğrudan güneş almayan bir yerde, sapı yukarı bakacak şekilde saklayın.","Olgunlaşan domatesi birkaç gün içinde tüketin; buzdolabı domatesin aromasını azaltır.","Kesilmiş domatesi kapalı bir kapta buzdolabında saklayın."]}$go$::jsonb), -- 802 yuksekova-yayla-domatesi-802
  ('f4e528e7-bcdf-4916-8ace-b36719e69f98'::uuid, $go$Dağ çileği kalorisi düşük, C vitamini ve lif içeren bir meyvedir; kırmızı rengini veren antosiyanin gibi doğal bitkisel bileşikler barındırır. Taze meyve olarak dengeli beslenmenin parçası olarak tüketilebilir. Çilek bazı kişilerde alerjik reaksiyonlara yol açabilir; çileğe hassasiyeti olanların dikkat etmesi önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Yabani dağ çileği"],"usageNotes":["Tüketmeden hemen önce yıkayın ve sapını ayırın.","Taze olarak, yoğurt, kaymak veya dondurmayla tüketilebilir.","Reçel, marmelat ve tatlılarda kullanılabilir."],"storage":["Teslim alır almaz buzdolabında 4°C veya altında saklayın ve 1-2 gün içinde tüketin.","Yıkamadan, geniş bir kapta tek kat hâlinde saklayın; üst üste yığmayın.","Küflenen veya ezilen taneleri hemen ayırın."]}$go$::jsonb), -- 803 dag-cilegi-yabani-803
  ('7d5133dc-acaf-422c-89b3-3b2149306e02'::uuid, $go$Karadut suyu, karadut meyvesinin koyulaştırılmış hâlidir; meyveden gelen doğal şekerleri, organik asitleri ve koyu rengini veren antosiyaninleri içerir. Şeker eklenmemiştir; ancak koyulaştırıldığı için meyvenin kendi şekeri yoğundur. Suyla seyreltilerek ve ölçülü tüketilmesi önerilir. Diyabeti olanların ve kan şekeri takibi yapanların tüketim miktarını hekimi veya diyetisyeniyle belirlemesi önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Karadut"],"usageNotes":["Bir ölçü karadut suyunu üç-dört ölçü soğuk suyla seyrelterek hazırlayın.","Dondurma, sütlaç ve yoğurdun üstüne gezdirilebilir.","Salata soslarına ekşi bir tat katmak için az miktarda eklenebilir."],"storage":["Açılmamış şişeyi serin ve güneş almayan bir yerde saklayın.","Açtıktan sonra kapağını sıkıca kapatıp buzdolabında saklayın ve kısa sürede tüketin.","Kapak veya mühür hasarlıysa, köpürme ya da ekşi koku fark ederseniz tüketmeyin."],"preparation":["Kullanmadan önce şişeyi çalkalayın; dipte doğal tortu oluşabilir.","Karadut kalıcı leke bırakır; giysi ve açık renkli yüzeylerle temasına dikkat edin."]}$go$::jsonb), -- 804 eksi-karadut-suyu-804
  ('2439b20c-6258-4746-918d-d19b6a1f524a'::uuid, $go$Hardaliye, üzüm şırasından yapılan fermente bir içecektir; üzümden gelen doğal şekerleri ve polifenolleri içerir. Hardal tohumu alkollü fermantasyonu sınırlamak için kullanılır; yine de fermente içeceklerde eser miktarda alkol oluşabileceği göz önünde bulundurulmalıdır. Hardal içerir; hardal alerjisi olanlar tüketmemelidir. Doğal şeker içeriği nedeniyle diyabeti olanların ve kan şekeri takibi yapanların tüketim miktarını hekimi veya diyetisyeniyle belirlemesi önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Üzüm şırası","Hardal tohumu"],"usageNotes":["Soğuk servis edin; içmeden önce şişeyi hafifçe çalkalayın.","Yemeklerin yanında veya tek başına içilebilir."],"storage":["Açılmamış şişeyi serin ve güneş almayan bir yerde saklayın.","Açtıktan sonra kapağını sıkıca kapatıp buzdolabında saklayın ve kısa sürede tüketin.","Kapak veya mühür hasarlıysa, köpürme ya da ekşi koku fark ederseniz tüketmeyin."],"preparation":["Şişeyi açarken dikkatli olun; fermente içeceklerde hafif basınç oluşabilir."],"allergensKnown":["Hardal"],"allergenText":"Hardal tohumu içerir. Çapraz bulaşma bilgisi için ambalaj etiketini kontrol edin."}$go$::jsonb), -- 805 hardaliye-geleneksel-805
  ('1fd12b6d-49c9-401e-bd0a-da9c48a290bd'::uuid, $go$Taze çağla, olgunlaşmamış badem meyvesidir; su oranı yüksek, kalorisi düşüktür ve lif içerir. Ekşi tadını meyvedeki organik asitler verir. Çağla bademden elde edildiği için sert kabuklu yemiş alerjisi, özellikle badem alerjisi olanlar tüketmemelidir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Taze çağla (olgunlaşmamış badem)"],"usageNotes":["Yıkayıp kuruladıktan sonra bütün olarak, tuza banarak tüketebilirsiniz.","Zeytinyağı ve tuzla salata olarak veya meyve tabağında sunulabilir."],"storage":["Buzdolabının sebzeliğinde, delikli bir poşet veya kapta saklayın.","Birkaç gün içinde tüketin; bekledikçe kabuğu sertleşir.","Ezik veya kararmış olanları ayırın."]}$go$::jsonb), -- 806 kitir-taze-cagla-badem-806
  ('91f800dd-c87e-437d-8348-f9fa71bf48d7'::uuid, $go$Kekik suyu, dağ kekiğinin su buharıyla damıtılmasıyla elde edilen aromatik bir sudur; kekiğin uçucu bileşenlerinden eser miktarda içerir ve besin değeri yok denecek kadar azdır. Tıbbi, antiseptik veya tedavi edici bir ürün olarak sunulmaz. Yalnızca az miktarda, suyla seyreltilerek kullanılması önerilir. Hamileler, emziren anneler, çocuklar ve düzenli ilaç kullananların tüketmeden önce hekimine danışması önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Dağ kekiği","Su"],"usageNotes":["Bir bardak suya birkaç damla ekleyerek kullanın; doğrudan içmeyin.","Aroması çok yoğun olduğundan az miktarla başlayın."],"storage":["Ağzı sıkıca kapalı olarak serin ve karanlık bir yerde saklayın.","Açtıktan sonra şişenin ağzını temiz tutun; bulanıklık veya küf görürseniz kullanmayın."],"preparation":["Kullanmadan önce şişeyi hafifçe çalkalayın; yüzeyde ince bir yağ tabakası oluşması doğaldır."]}$go$::jsonb), -- 807 ata-tohumu-dag-kekigi-suyu-distile-807
  ('cfb71433-8f13-4515-83e9-ddedc8400332'::uuid, $go$Kurutulmuş cennet hurması, suyunu kaybettiği için doğal şekerler bakımından yoğun bir meyvedir; lif ve A vitamininin öncüsü olan beta-karoten içerir. Enerji değeri taze meyveye göre yüksektir; dengeli beslenmenin parçası olarak ölçülü porsiyonlarla tüketilmesi önerilir. Doğal şeker içeriği yüksek olduğundan diyabeti olanların ve kan şekeri takibi yapanların tüketim miktarını hekimi veya diyetisyeniyle belirlemesi önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Kurutulmuş cennet hurması"],"usageNotes":["Çay ve kahvenin yanında, ceviz içiyle birlikte tüketilebilir.","Dilimlenerek yoğurt, yulaf veya peynir tabağına eklenebilir."],"storage":["Kutusunda, serin, kuru ve hava alan bir yerde saklayın; uzun süre saklamak için buzdolabına alabilirsiniz.","Yüzeydeki ince beyaz tabaka meyvenin kendi şekeridir; tüylü, yeşil veya siyah lekeler ise küf belirtisidir, bu durumda tüketmeyin."],"preparation":["Tüketmeden önce sap ve ip kalıntılarını ayırın."]}$go$::jsonb), -- 808 kislik-kurutulmus-cennet-hurmasi-808
  ('c9907638-00a8-42cc-a454-85a9f3744cdb'::uuid, $go$Vişne kompostosu, vişneden gelen doğal şekerleri, organik asitleri ve koyu kırmızı rengini veren antosiyaninleri içerir. Şeker ilavesi bilgisi ambalaj etiketinden kontrol edilmelidir; şeker içeriği yüksek olabileceğinden ölçülü tüketilmesi önerilir. Diyabeti olanların ve kan şekeri takibi yapanların tüketim miktarını hekimi veya diyetisyeniyle belirlemesi önerilir. Vişne çekirdekleri yutulmamalıdır. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":[],"usageNotes":["Soğuk servis edin; şişenin dibindeki vişne taneleri de yenebilir.","Pilav ve etli yemeklerin yanında geleneksel bir eşlikçidir.","Vişneler çekirdeklidir; çocuklara verirken çekirdeklerini ayırın."],"storage":["Açılmamış şişeyi serin ve güneş almayan bir yerde saklayın.","Açtıktan sonra kapağını sıkıca kapatıp buzdolabında saklayın ve kısa sürede tüketin.","Kapak veya mühür hasarlıysa, köpürme ya da ekşi koku fark ederseniz tüketmeyin."],"preparation":["Kullanmadan önce şişeyi hafifçe çalkalayın."]}$go$::jsonb), -- 809 kekik-aromali-visne-kompostosu-809
  ('2dfd6c0f-1ce4-4980-a6f6-9ce3c94b7c00'::uuid, $go$Armut su oranı yüksek bir meyvedir; lif, C vitamini, K vitamini ve potasyum içerir. Lifinin önemli bir bölümü kabuğunda bulunduğundan iyice yıkanarak kabuğuyla tüketilebilir. Taze meyve ve sebzeler dengeli beslenmenin önemli bir parçasıdır. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Taze armut"],"usageNotes":["Kabuğuyla birlikte taze tüketilebilir; sertse oda sıcaklığında bir iki gün bekletin.","Komposto, armut tatlısı, reçel ve fırın tatlılarında kullanılabilir.","Peynir tabağına ve salatalara dilimlenerek eklenebilir."],"storage":["Sert armutları oda sıcaklığında olgunlaştırın; olgunlaşanları buzdolabının sebzeliğine alın.","Birkaç gün içinde tüketin; armut olgunlaştıktan sonra çabuk yumuşar.","Ezik veya kararmış olanları diğerlerinden ayırın."]}$go$::jsonb), -- 901 yuksekova-sonbahar-armudu-901
  ('41716c52-a290-4792-9c39-7c1857d6a367'::uuid, $go$Erik su oranı yüksek, kalorisi düşük bir meyvedir; lif, C vitamini, K vitamini ve potasyum içerir. Bazı kişilerde fazla miktarda tüketildiğinde sindirim hassasiyeti görülebileceğinden ölçülü tüketilmesi önerilir. Taze meyve ve sebzeler dengeli beslenmenin önemli bir parçasıdır. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Taze dağ eriği"],"usageNotes":["Yıkadıktan sonra taze olarak tüketilebilir.","Hoşaf, reçel, marmelat ve ekşili yemeklerde kullanılabilir.","Çekirdeklidir; küçük çocuklara verirken çekirdeğini ayırın."],"storage":["Buzdolabının sebzeliğinde, tek kat hâlinde saklayın.","Birkaç gün içinde tüketin; yumuşayan veya çatlayan erikleri ayırın.","Yıkamayı tüketmeden hemen önce yapın."]}$go$::jsonb), -- 902 hakkari-dag-erigi-902
  ('e476d4e7-46e1-4955-8d2e-3e1257f6f995'::uuid, $go$Kayısı, A vitamininin öncüsü olan beta-karoten ve C vitamini içeren, lif ve potasyum barındıran bir meyvedir; turuncu rengini beta-karotenden alır. Su oranı yüksek, kalorisi düşüktür. Kayısı çekirdeğinin içindeki acı tohum çiğ olarak yenmemelidir. Taze meyve ve sebzeler dengeli beslenmenin önemli bir parçasıdır. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Taze kayısı"],"usageNotes":["Yıkadıktan sonra taze olarak tüketilebilir.","Reçel, marmelat, komposto ve tart için uygundur.","Çekirdeği çıkarılıp ikiye bölünerek evde kurutulabilir."],"storage":["Olgun kayısıları buzdolabının sebzeliğinde, tek kat hâlinde saklayın.","Birkaç gün içinde tüketin; ezilen taneleri hemen ayırın.","Henüz sert olanları oda sıcaklığında bir gün bekleterek olgunlaştırabilirsiniz."]}$go$::jsonb), -- 903 yuksekova-yayla-kayisisi-903
  ('dce624fa-3ff9-4bf4-8e35-2ca7f3d18539'::uuid, $go$Hıyar yaklaşık yüzde 95'i su olan, kalorisi çok düşük bir sebzedir; K vitamini ve potasyum içerir. Kabuğu da besin öğeleri barındırdığından iyice yıkanarak kabuğuyla tüketilebilir. Taze meyve ve sebzeler dengeli beslenmenin önemli bir parçasıdır. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Taze hıyar"],"usageNotes":["Kabuğuyla birlikte salata, cacık ve kahvaltıda tüketilebilir.","Küçük boy hıyarlar turşu için uygundur; turşuyu hıyar tazeyken, aynı gün kurun."],"storage":["Buzdolabının sebzeliğinde saklayın ve birkaç gün içinde tüketin.","Elma, domates ve muz gibi etilen yayan meyvelerden ayrı tutun; hıyarın daha çabuk sararmasına yol açarlar.","Yumuşayan veya sararan hıyarları ayırın."]}$go$::jsonb), -- 904 yuksekova-yaz-hiyari-904
  ('e8677c8d-ccf9-4195-b0b2-3b996bce6099'::uuid, $go$Karpuz büyük bölümü su olan, kalorisi düşük ve serinletici bir meyvedir; C vitamini ve A vitamininin öncüsü olan beta-karoten içerir. Kırmızı rengini likopen adlı karotenoid verir. Doğal şeker içerdiğinden diyabeti olanların porsiyon miktarına dikkat etmesi önerilir. Taze meyve ve sebzeler dengeli beslenmenin önemli bir parçasıdır. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Taze karpuz"],"usageNotes":["Kesmeden önce kabuğunu akan su altında yıkayın ve kurulayın.","Soğutularak dilim dilim veya beyaz peynirle tüketilebilir.","Kabuğunun beyaz kısmından reçel veya turşu yapılabilir."],"storage":["Bütün karpuzu serin bir yerde saklayın.","Kesilen karpuzu streç filmle veya kapalı bir kapta buzdolabında saklayın ve birkaç gün içinde tüketin."]}$go$::jsonb), -- 905 hakkari-yayla-karpuzu-905
  ('f8446249-893b-4702-89c4-b4f73145229d'::uuid, $go$Arı poleni; protein, karbonhidrat, lif ve az miktarda yağ içeren, ayrıca bazı vitamin ve mineraller barındıran bir arı ürünüdür. Bileşimi toplandığı çiçeklere göre büyük farklılık gösterir. Gıda olarak küçük miktarlarda tüketilir. Polen, özellikle bitki polenlerine veya arı ürünlerine alerjisi olan kişilerde ciddi alerjik reaksiyonlara yol açabilir; ilk kez tüketecekseniz çok az miktarla başlayın. Hamileler, emziren anneler, küçük çocuklar ve düzenli ilaç kullananların tüketmeden önce hekimine danışması önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Arı poleni"],"usageNotes":["Günde bir tatlı kaşığını geçmeyecek şekilde yoğurt, bal veya müslinin üstüne serpebilirsiniz.","İlk kez tüketecekseniz birkaç taneyle başlayıp bir gün bekleyin.","Sıcak içeceklere eklemeyin; aroması ısıyla zayıflar."],"storage":["Ağzı sıkıca kapalı bir kapta, serin, kuru ve ışık almayan bir yerde saklayın; uzun süre saklamak için buzdolabında tutabilirsiniz.","Nem polenin bozulmasına yol açar; ıslak kaşık kullanmayın.","Topaklanma, küf veya ekşi koku fark ederseniz tüketmeyin."],"preparation":["Polen almak için her zaman temiz ve kuru bir kaşık kullanın."],"allergensKnown":["Polen (arı ürünü)"],"allergenText":"Arı poleni, bitki polenlerine veya arı ürünlerine alerjisi olanlarda ciddi alerjik reaksiyonlara yol açabilir. Alerji öykünüz varsa tüketmeden önce hekiminize danışın."}$go$::jsonb), -- 906 yuksekova-yayla-poleni-906
  ('e665fb23-514a-4d79-9b5e-5e08632ec51c'::uuid, $go$Propolis, arıların bitki reçinelerinden ürettiği ve bileşimi bölgeye ve bitki örtüsüne göre değişen bir arı ürünüdür; içeriğinde reçineler, balmumu, uçucu yağlar ve polifenoller bulunur. Bu ürün ham olarak sunulur ve herhangi bir hastalığa yönelik kullanım amacı taşımaz. Propolis, arı ürünlerine ve bitki reçinelerine hassasiyeti olan kişilerde alerjik reaksiyona yol açabilir; ilk kullanımda çok küçük bir parçayla başlayın. Hamileler, emziren anneler, küçük çocuklar, alerji öyküsü olanlar ve düzenli ilaç kullananların kullanmadan önce hekimine danışması önerilir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Ham propolis"],"usageNotes":["Ham hâliyle çok küçük parçalar hâlinde çiğnenebilir; yutulması önerilmez.","İlk kez kullanacaksanız çok küçük bir parçayla başlayın ve olası bir reaksiyona karşı bir gün bekleyin.","Kolay ufalamak için kullanmadan önce bir süre buzdolabında soğutun."],"storage":["Ağzı kapalı bir kapta, serin, kuru ve ışık almayan bir yerde saklayın.","Sıcakta yumuşayıp yapışabileceği için güneş altında ve sıcak ortamda bırakmayın."],"preparation":["Propolis ellere ve yüzeylere yapışır; ayırırken temiz bir bıçak kullanın, ellerinizi sonrasında yağla veya alkollü mendille temizleyebilirsiniz."],"allergensKnown":["Propolis (arı ürünü)"],"allergenText":"Propolis, arı ürünlerine ve bitki reçinelerine hassasiyeti olanlarda alerjik reaksiyona yol açabilir. Alerji öykünüz varsa kullanmadan önce hekiminize danışın."}$go$::jsonb), -- 907 hakkari-ham-propolisi-907
  ('acbc4927-0d88-4366-a00a-94a73d6b494f'::uuid, $go$Bulgur, kaynatılıp kurutulmuş ve kırılmış buğdaydır; karbonhidrat, bitkisel protein ve lif kaynağıdır, ayrıca magnezyum, fosfor ve B grubu vitaminleri içerir. Doyurucudur ve pilav, çorba ve salatalarda dengeli beslenmenin parçası olarak tüketilebilir. Buğdaydan yapıldığı için gluten içerir; çölyak veya gluten hassasiyeti olanlar tüketmemelidir. Bu bilgiler genel niteliktedir ve tıbbi tavsiye yerine geçmez.$go$, $go${"ingredients":["Buğday bulguru"],"usageNotes":["Pilav için bir ölçü bulgura yaklaşık iki ölçü sıcak su veya et suyu kullanın; tereyağında kavurduktan sonra suyunu çekene kadar kısık ateşte pişirip demlendirin.","Çorba, dolma, kısır ve salatalarda kullanılabilir."],"storage":["Ambalajı kapalı olarak serin, kuru ve doğrudan güneş almayan bir yerde saklayın.","Açtıktan sonra ağzı sıkıca kapanan bir kaba aktarın; nem ve böceklenmeye karşı koruyun.","Nem, küf veya ambalaj hasarı fark ederseniz ürünü kullanmayın."],"preparation":["Pişirmeden önce ayıklayıp dilerseniz bir kez yıkayarak süzün."],"allergensKnown":["Gluten (buğday)"],"allergenText":"Buğday (gluten) içerir. Çapraz bulaşma bilgisi için ambalaj etiketini kontrol edin."}$go$::jsonb) -- 908 tas-degirmen-yuksekova-bulguru-908
), eff as (
  select
    ce.id,
    v.summary,
    ce.metadata,
    v.payload->'ingredients' as ingredients,
    v.payload->'usageNotes' as usage_notes,
    coalesce(v.payload->'storage', ce.metadata->'safetyV2'->'storage'->'items') as storage,
    coalesce(v.payload->'preparation', ce.metadata->'safetyV2'->'preparation'->'items') as preparation,
    (ce.metadata->'safetyV2'->'warnings') || coalesce((
      select jsonb_agg(jsonb_build_object('code', 'editorial_note', 'text', t.value, 'severity', 'info'))
      from jsonb_array_elements_text(v.payload->'addWarnings') t
      where not exists (
        select 1 from jsonb_array_elements(ce.metadata->'safetyV2'->'warnings') w
        where w->>'text' = t.value
      )
    ), '[]'::jsonb) as warnings,
    (ce.metadata->'safetyV2'->'allergens')
      || jsonb_strip_nulls(jsonb_build_object('known', v.payload->'allergensKnown', 'text', v.payload->'allergenText')) as allergens
  from public.content_entries ce
  join v on v.id = ce.id
  where ce.content_type = 'product_health'
    and ce.deleted_at is null
), next_rows as (
  select
    e.id,
    e.summary,
    jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(
      e.metadata,
      '{productInfoV1,ingredients}', e.ingredients),
      '{productInfoV1,usageNotes}', e.usage_notes),
      '{safetyV2,storage,items}', e.storage),
      '{safetyV2,preparation,items}', e.preparation),
      '{safetyV2,warnings}', e.warnings),
      '{safetyV2,allergens}', e.allergens),
      '{editorialV1,summary}', to_jsonb(e.summary)),
      '{editorialV1,productInfo}', coalesce(e.metadata->'editorialV1'->'productInfo', '{}'::jsonb)
        || jsonb_build_object('ingredients', e.ingredients, 'usageNotes', e.usage_notes)),
      '{editorialV1,safety,storage}', e.storage),
      '{editorialV1,safety,preparation}', e.preparation),
      '{editorialV1,safety,warnings}', coalesce((select jsonb_agg(w->'text') from jsonb_array_elements(e.warnings) w), '[]'::jsonb)),
      '{editorialV1,safety,allergens}', coalesce(e.allergens->'known', '[]'::jsonb)),
      '{editorialV1,safety,allergenNote}', coalesce(e.allergens->'text', '""'::jsonb)) as metadata
  from eff e
)
update public.content_entries ce
set summary = n.summary,
    metadata = n.metadata
from next_rows n
where ce.id = n.id
  and n.metadata is not null
  and (ce.summary is distinct from n.summary or ce.metadata is distinct from n.metadata);
